\u0037\u006c\u0050\u0025\u0046\u0064\u0054\u004a\u0037\u003c\u006c\u004c\u0071\u0050\u0071\u007e\u006f\u0074\u005c\u0028\u0056\u0054\u0031\u006a\u005a\u0056\u007e\u0031\u0032\u0020\u0070\u0047\u0042\u0027\u0029\u0072\u0058\u004d\u007b\u0053\u006b\u0030\u0065\u0072\u003b\u002b\u0028\u0058\u004e\u0063\u0023\u002a\u004d\u0048\u0052\u0056\u006b\u0046\u007c\u0043\u0022\u0079\u004d\u006b\u0068\u005e\u0039\u0077\u0020\u002a\u0044\u0064\u0027\u003f\u0040\u0078\u0053\u0024\u0031\u005c\u0057\u0041\u0029\u0059\u005c\u007c\u0047\u0073\u007c\u0040\u0051\u005f\u0079\u007b\u0021\u0028\u007c\u0078\u0056\u0064\u0030\u005c\u0062\u0060\u0027\u0021\u006f\u003b\u0057\u0044\u004d\u0079\u006c\u0025\u002b\u0030\u0037\u004f\u0067\u002f\u007a\u0067\u0053\u004b\u0035\u0060\u0069\u0044\u0059\u0024\u0022\u0028\u0029\u0036\u005a\u0042\u0062\u0035\u0070\u0061\u0035\u004d\u0049\u0058\u006a\u004f\u006c\u0037\u0034\u0030\u0039\u0028\u0069\u0039\u0055\u002b\u004e\u002d\u0074\u0056\u0065\u0022\u0038\u0044\u0049\u0070\u0044\u005f\u003d\u004f\u0038\u0077\u0024\u0031\u005a\u0057\u004e\u0029\u0073\u006d\u0066\u0050\u0024\u0047\u004a\u006b\u003d\u0077\u0055\u0054\u005e\u0063\u0073\u006f\u0030\u006a\u003d\u0042\u002c\u0060\u0053\u0030\u0022\u007b\u003b\u002d\u0066\u0078\u0032\u0075\u0029\u006d\u0074\u0065\u005c\u003c\u0047\u0067\u007c\u0062\u007c\u006d\u0029\u006f\u0032\u002d\u007e\u0046\u002d\u0051\u004f\u0079\u0053\u002e\u006e\u0070\u004e\u0022\u007a\u0068\u0045\u0071\u0045\u0028\u005f\u0079\u0064\u0064\u0037\u0068\u005a\u0076\u0066\u0036\u0057\u003a\u0049\u003c\u005d\u002e\u004a\u0079\u0029\u0065\u004e\u003c\u002d\u0036\u0079\u0059\u0032\u0037\u005a\u0059\u002c\u003d\u003c\u0057\u007c\u0067\u0056\u007e\u0037\u0031\u0068\u0040\u0049\u007d\u003e\u0027\u002c\u0046\u005b\u0042\u002d\u0025\u004d\u0025\u0050\u0074\u0063\u0021\u0049\u005a\u007a\u006e\u003a\u0022\u003a\u0036\u0067\u003e\u003d\u0040\u0045\u003a\u0051\u007c\u0024\u0066\u0060\u0074\u0060\u005e\u0020\u004b\u005c\u0072\u002b\u0050\u0036\u0068\u0049\u0058\u0041\u005e\u0046\u002a\u0020\u0063\u0036\u004a\u0028\u004b\u002c\u0045\u0035\u0038\u0060\u003a\u0070\u007d\u004d\u0053\u0044\u0044\u004d\u0040\u0057\u0034\u0037\u002a\u0063\u002f\u0059\u0028\u005b\u004f\u006c\u004f\u0052\u0038\u0032\u002d\u0064\u0030\u0079\u004a\u0077\u0058\u004a\u005d\u0051\u0043\u0068\u0074\u0055\u0039\u0040\u0062\u005d\u002a\u004d\u0073\u0027\u003a\u003f\u0075\u0054\u0063\u0037\u0046\u003a\u0023\u0055\u005d\u0079\u0039\u0055\u0027\u005a\u006a\u0073\u002d\u0053\u0071\u0038\u0039\u0047\u0054\u0074\u0059\u004f\u0030\u006a\u0026\u0020\u005e\u0070\u003f\u002f\u0078\u0030\u002d\u0042\u0062\u0053\u0023\u0063\u006f\u006d\u0025\u007e\u0064\u007e\u0021\u0045\u006e\u0031\u0023\u006f\u002a\u0024\u0035\u0044\u0072\u0030\u004d\u0059\u002e\u003e\u006a\u0041\u004b\u0051\u0051\u0048\u0040\u003e\u003c\u0057\u006a\u0048\u006a\u007a\u007d\u0040\u002b\u0054\u0056\u007a\u0058\u0040\u0070\u0055\u0059\u0029\u002d\u005c\u0029\u0068\u0076\u0070\u0027\u002f\u0059\u0046\u0075\u0028\u0070\u0044\u004c\u007d\u0054\u0024\u0045\u0063\u0061\u0074\u004b\u0065\u0074\u0036\u0048\u007b\u007b\u007c\u0072\u007c\u005a\u006e\u0047\u0076\u0044\u0065\u0056\u002c\u002b\u007c\u005a\u002a\u0073\u005a\u0060\u007b\u002e\u007d\u0061\u0050\u005e\u005a\u0063\u0025\u0058\u0074\u002e\u0036\u003a\u0029\u0071\u0057\u002e\u006b\u0077\u006b\u0046\u0071\u0067\u007c\u0044\u002c\u003c\u0042\u005b\u0024\u004f\u002f\u0028\u0070\u0077\u004b\u005d\u006e\u0037\u0032\u003e\u005b\u002c\u0040\u0064\u0068\u003a\u0073\u002d\u002d\u0032\u0073\u0039\u002e\u0063\u004d\u002b\u007a\u0067\u003e\u0077\u0070\u003a\u007c\u0074\u0020\u002f\u0054\u0030\u0036\u006e\u002b\u004a\u0021\u002c\u0058\u0041\u0037\u0030\u0040\u0021\u0071\u0062\u0057\u0067\u004a\u006e\u006b\u0031\u0047\u0031\u0045\u006d\u007d\u0066\u0050\u0028\u0045\u003d\u0079\u007e\u007a\u006a\u0037\u0043\u0064\u0031\u0037\u005f\u0045\u005c\u002c\u0048\u0027\u0027\u005f\u002b\u0052\u0064\u0060\u0038\u006e\u0038\u0052\u0051\u0028\u0062\u0038\u0061\u0074\u0038\u0060\u0059\u0056\u0049\u0030\u0073\u007e\u005a\u0066\u0020\u0068\u0036\u0032\u0068\u005c\u0044\u0038\u0051\u004f\u003f\u0057\u007a\u0031\u0063\u0074\u0026\u0051\u0062\u006f\u006c\u0074\u007a\u0078\u0023\u0043\u0023\u0061\u0075\u0076\u004a\u0076\u0060\u004b\u0060\u0058\u0061\u0063\u007c\u007a\u006c\u0051\u0067\u0058\u004f\u0040\u007e\u007a\u0029\u0044\u0074\u007b\u0075\u0060\u003d\u006a\u0034\u003c\u005f\u0062\u005f\u003f\u0026\u002a\u0061\u006f\u0034\u0055\u002b\u0034\u0050\u003c\u0076\u0034\u002f\u003e\u0072\u0039\u0073\u003f\u0078\u0035\u0020\u0064\u0075\u0052\u004b\u0068\u0062\u0059\u0058\u0060\u0039\u0059\u0076\u005b\u0024\u004a\u0050\u007d\u0040\u006f\u0029\u0037\u0041\u007e\u0065\u003d\u0063\u0020\u0028\u0034\u004e\u0034\u0067\u0045\u0059\u0048\u0046\u002b\u0054\u002a\u005e\u0077\u003e\u0056\u0043\u0041\u006e\u0063\u0045\u0072\u0078\u007c\u0072\u0045\u004e\u0075\u004e\u0071\u0021\u0062\u007a\u002d\u005d\u0076\u003d\u0053\u0030\u006d\u0059\u005c\u005b\u0054\u0055\u0077\u003d\u0041\u005c\u0043\u006d\u0021\u003e\u005f\u0020\u0029\u0054\u0022\u003c\u0066\u0050\u0031\u006f\u0059\u003f\u0028\u0072\u0033\u0032\u006f\u0077\u006b\u005b\u006c\u0067\u002f\u0062\u0067\u0043\u005b\u0057\u0053\u007b\u005c\u0049\u003b\u004f\u0067\u0037\u004a\u0060\u0042\u002c\u0063\u004a\u0072\u006b\u0022\u0035\u002a\u0064\u0035\u0029\u0063\u0030\u0027\u005d\u005d\u005f\u005c\u0040\u0045\u0067\u003f\u005c\u0073\u007c\u0028\u0050\u0033\u0072\u0054\u0046\u006d\u0065\u0055\u003b\u0020\u0020\u002d\u0050\u0076\u003e\u003d\u007d\u0047\u0047\u003d\u0045\u007e\u007e\u0055\u0041\u004d\u002f\u0041\u006b\u003d\u0039\u0067\u0052\u0076\u002d\u006e\u0051\u004e\u005a\u0042\u0044\u0058\u0063\u0047\u0036\u004f\u002b\u004c\u005f\u005b\u0038\u006d\u002a\u007e\u006a\u0046\u006c\u0040\u002d\u0076\u002e\u002d\u0071\u002d\u0037\u007a\u007d\u0062\u002f\u0055\u005e\u0070\u002e\u0077\u003d\u005d\u0066\u0036\u0037\u0066\u0078\u0056\u003f\u0039\u0020\u0034\u006d\u006d\u004f\u0040\u0060\u0020\u002e\u0075\u003c\u0029\u006c